cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

#define TILE_H 64
#define TILE_W 64
#define BLOCK_H 16
#define BLOCK_W 16
template <int OC_CAP>
__global__ void conv2d_kernel(
    const cute::bfloat16_t* __restrict__ in_ptr,
    const cute::bfloat16_t* __restrict__ w_ptr,
    cute::bfloat16_t* __restrict__ out_ptr,
    int N, int IC, int H, int W,
    int OC, int KH, int KW,
    int OH, int OW)
{
    // Global tensors described with CuTe layouts
    Tensor gIn = make_tensor(make_gmem_ptr(in_ptr),
                              make_shape(N, IC, H, W),
                              make_stride(IC * H * W, H * W, W, 1));
    Tensor gOut = make_tensor(make_gmem_ptr(out_ptr),
                               make_shape(N, OC, OH, OW),
                               make_stride(OC * OH * OW, OH * OW, OW, 1));
    int n = blockIdx.z;
    int tile_row = blockIdx.y * TILE_H;
    int tile_col = blockIdx.x * TILE_W;
    int tx = threadIdx.x; // 0..BLOCK_W-1
    int ty = threadIdx.y; // 0..BLOCK_H-1
    extern __shared__ __align__(16) unsigned char smem_raw[];
    cute::bfloat16_t* s_in = reinterpret_cast<cute::bfloat16_t*>(smem_raw);
    const int in_tile_h = TILE_H + KH - 1;
    const int in_tile_w = TILE_W + KW - 1;
    int in_tile_elems = IC * in_tile_h * in_tile_w;
    int in_tile_elems_padded = (in_tile_elems + 7) & ~7; // pad to 16B (8 x bf16) boundary
    cute::bfloat16_t* s_w = s_in + in_tile_elems_padded;
    // Shared memory tensors via CuTe (mixed static/dynamic layouts)
    Tensor sIn = make_tensor(make_smem_ptr(s_in),
                              make_shape(IC, in_tile_h, in_tile_w),
                              make_stride(in_tile_h * in_tile_w, in_tile_w, 1));
    Tensor sW = make_tensor(make_smem_ptr(s_w),
                             make_shape(OC, IC, KH, KW),
                             make_stride(IC * KH * KW, KH * KW, KW, 1));
    int tid = ty * BLOCK_W + tx;
    int nthreads = BLOCK_H * BLOCK_W;
    // Cooperative load of weights into shared memory using 128-bit vectorized
    // transfers (8 bf16 elements per transaction) to improve global memory
    // coalescing and reduce the number of load/store instructions issued.
    int wsize = OC * IC * KH * KW;
    int wsize_vec = wsize / 8;
    const uint4* w_ptr_vec = reinterpret_cast<const uint4*>(w_ptr);
    uint4* s_w_vec = reinterpret_cast<uint4*>(s_w);
    for (int i = tid; i < wsize_vec; i += nthreads) {
        s_w_vec[i] = w_ptr_vec[i];
    }
    int wrem_start = wsize_vec * 8;
    for (int i = wrem_start + tid; i < wsize; i += nthreads) {
        s_w[i] = w_ptr[i];
    }
    // Cooperative load of input tile (with halo) into shared memory
    int in_tile_size = IC * in_tile_h * in_tile_w;
    for (int i = tid; i < in_tile_size; i += nthreads) {
        int c = i / (in_tile_h * in_tile_w);
        int rem = i % (in_tile_h * in_tile_w);
        int r = rem / in_tile_w;
        int cc = rem % in_tile_w;
        int gh = tile_row + r;
        int gw = tile_col + cc;
        cute::bfloat16_t val = cute::bfloat16_t(0.0f);
        if (gh < H && gw < W) {
            val = gIn(n, c, gh, gw);
        }
        sIn(c, r, cc) = val;
    }
    __syncthreads();
    // Register-blocked output computation: each thread computes a 4x4
    // block of outputs within the 64x64 output tile. Increasing the
    // per-thread register block from 2x2 to 4x4 quadruples the reuse of
    // both the shared-memory input tile and the shared-memory weights
    // per element loaded, substantially raising arithmetic intensity and
    // amortizing the cost of staging the (larger) input tile into shared
    // memory -- important given the very large output volume of this
    // convolution (N * OC * OH * OW).
    int local_h[4] = {ty, ty + BLOCK_H, ty + 2 * BLOCK_H, ty + 3 * BLOCK_H};
    int local_w[4] = {tx, tx + BLOCK_W, tx + 2 * BLOCK_W, tx + 3 * BLOCK_W};
    int oh_arr[4] = {tile_row + local_h[0], tile_row + local_h[1], tile_row + local_h[2], tile_row + local_h[3]};
    int ow_arr[4] = {tile_col + local_w[0], tile_col + local_w[1], tile_col + local_w[2], tile_col + local_w[3]};
    bool valid[4][4];
    #pragma unroll
    for (int rh = 0; rh < 4; ++rh) {
        #pragma unroll
        for (int rw = 0; rw < 4; ++rw) {
            valid[rh][rw] = (oh_arr[rh] < OH) && (ow_arr[rw] < OW);
        }
    }
    // Output-channel tiling: process OC in small chunks so the per-thread
    // accumulator register footprint (16 sub-outputs x OC_TILE) stays
    // bounded regardless of OC, avoiding register-file pressure/spilling.
    const int OC_TILE = 8;
    for (int oc_base = 0; oc_base < OC; oc_base += OC_TILE) {
        float acc[4][4][OC_TILE];
        #pragma unroll
        for (int rh = 0; rh < 4; ++rh) {
            #pragma unroll
            for (int rw = 0; rw < 4; ++rw) {
                #pragma unroll
                for (int t = 0; t < OC_TILE; ++t) {
                    acc[rh][rw][t] = 0.0f;
                }
            }
        }
        for (int c = 0; c < IC; ++c) {
            for (int kh = 0; kh < KH; ++kh) {
                for (int kw = 0; kw < KW; ++kw) {
                    float a[4][4];
                    #pragma unroll
                    for (int rh = 0; rh < 4; ++rh) {
                        #pragma unroll
                        for (int rw = 0; rw < 4; ++rw) {
                            a[rh][rw] = float(sIn(c, local_h[rh] + kh, local_w[rw] + kw));
                        }
                    }
                    #pragma unroll
                    for (int t = 0; t < OC_TILE; ++t) {
                        int oc = oc_base + t;
                        if (oc < OC) {
                            float b = float(sW(oc, c, kh, kw));
                            #pragma unroll
                            for (int rh = 0; rh < 4; ++rh) {
                                #pragma unroll
                                for (int rw = 0; rw < 4; ++rw) {
                                    acc[rh][rw][t] += a[rh][rw] * b;
                                }
                            }
                        }
                    }
                }
            }
        }
        #pragma unroll
        for (int rh = 0; rh < 4; ++rh) {
            #pragma unroll
            for (int rw = 0; rw < 4; ++rw) {
                if (valid[rh][rw]) {
                    #pragma unroll
                    for (int t = 0; t < OC_TILE; ++t) {
                        int oc = oc_base + t;
                        if (oc < OC) {
                            gOut(n, oc, oh_arr[rh], ow_arr[rw]) = cute::bfloat16_t(acc[rh][rw][t]);
                        }
                    }
                }
            }
        }
    }
}
torch::Tensor cute_conv2d(torch::Tensor input, torch::Tensor weight) {
    TORCH_CHECK(input.is_cuda() && weight.is_cuda(), "input and weight must be CUDA tensors");
    TORCH_CHECK(input.dim() == 4 && weight.dim() == 4, "input and weight must be 4D");
    TORCH_CHECK(input.scalar_type() == at::kBFloat16 && weight.scalar_type() == at::kBFloat16,
                "expect bfloat16 tensors");
    auto input_c = input.contiguous();
    auto weight_c = weight.contiguous();
    int N = (int)input_c.size(0);
    int IC = (int)input_c.size(1);
    int H = (int)input_c.size(2);
    int W = (int)input_c.size(3);
    int OC = (int)weight_c.size(0);
    int KC = (int)weight_c.size(1);
    int KH = (int)weight_c.size(2);
    int KW = (int)weight_c.size(3);
    TORCH_CHECK(KC == IC, "channel mismatch between input and weight");
    TORCH_CHECK(OC <= 64, "OC exceeds maximum supported output channels (64) for this kernel");
    int OH = H - KH + 1;
    int OW = W - KW + 1;
    TORCH_CHECK(OH > 0 && OW > 0, "invalid output size");
    auto output = torch::empty({N, OC, OH, OW}, input_c.options());
    dim3 block(BLOCK_W, BLOCK_H);
    dim3 grid((OW + TILE_W - 1) / TILE_W, (OH + TILE_H - 1) / TILE_H, N);
    int in_tile_h = TILE_H + KH - 1;
    int in_tile_w = TILE_W + KW - 1;
    int in_tile_elems_host = IC * in_tile_h * in_tile_w;
    int in_tile_elems_padded_host = (in_tile_elems_host + 7) & ~7;
    size_t smem_bytes = (size_t)(in_tile_elems_padded_host + OC * IC * KH * KW) * sizeof(cute::bfloat16_t);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
