        conv2d_kernel<32><<<grid, block, smem_bytes, stream>>>(
            reinterpret_cast<const cute::bfloat16_t*>(input_c.data_ptr<at::BFloat16>()),
            reinterpret_cast<const cute::bfloat16_t*>(weight_c.data_ptr<at::BFloat16>()),
            reinterpret_cast<cute::bfloat16_t*>(output.data_ptr<at::BFloat16>()),
            N, IC, H, W, OC, KH, KW, OH, OW);
    } else {
        conv2d_kernel<64><<<grid, block, smem_bytes, stream>>>(
            reinterpret_cast<const cute::bfloat16_t*>(input_c.data_ptr<at::BFloat16>()),
            reinterpret_cast<const cute::bfloat16_t*>(weight_c.data_ptr<at::BFloat16>()),
            reinterpret_cast<cute::bfloat16_t*>(output.data_ptr<at::BFloat16>()),
            N, IC, H, W, OC, KH, KW, OH, OW);
    }
    return output;
}
"""

