    name="cute_conv2d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_conv2d"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "-std=c++17"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        # Keep an nn.Conv2d purely to hold/init the weight parameter identically to reference model.
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=32, kernel_size=3, bias=False, dtype=torch.bfloat16)
        self._ext = cute_ext

    def forward(self, x):
        return self._ext.cute_conv2d(x, self.conv1.weight)

